from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
import json
from pathlib import Path
import random
import time
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from .io import sha256_text


MODEL_ID = "Qwen/Qwen3-4B-GGUF"
PROMPT_VERSION = "kl-p4-text-only-short-answer-v1"
MODES = ("question_only", "lens_compact", "lens_balanced", "lens_detailed")
SYSTEM_INSTRUCTION = (
    "Answer the visual question using only the supplied visual evidence. "
    "If the evidence is insufficient, answer unknown. "
    'Return exactly one JSON object in the form {"answer":"short answer"}. /no_think'
)
GENERATION_CONFIG = {
    "temperature": 0.7,
    "top_p": 0.8,
    "top_k": 20,
    "min_p": 0.0,
    "presence_penalty": 1.5,
    "max_tokens": 32,
    "seed": -1,
    "stream": True,
    "stream_options": {"include_usage": True},
    "chat_template_kwargs": {"enable_thinking": False},
    "response_format": {
        "type": "json_schema",
        "json_schema": {
            "name": "short_answer",
            "strict": True,
            "schema": {
                "type": "object",
                "properties": {"answer": {"type": "string"}},
                "required": ["answer"],
                "additionalProperties": False,
            },
        },
    },
}


def request_text(question: str, mode: str, lens_text: str | None = None) -> str:
    if mode == "question_only":
        evidence = "Visual evidence: none."
    elif mode in {"lens_compact", "lens_balanced", "lens_detailed"}:
        if lens_text is None:
            raise ValueError(f"{mode} requires lens_text")
        evidence = f"Visual evidence:\n{lens_text}"
    else:
        raise ValueError(f"unknown text-only benchmark mode: {mode}")
    return f"{evidence}\nQuestion: {question}"


def cache_key(
    model_sha256: str,
    question_id: str,
    mode: str,
    lens_description_sha256: str | None,
    repeat_index: int,
) -> str:
    value = {
        "model_id": MODEL_ID,
        "model_sha256": model_sha256,
        "question_id": question_id,
        "mode": mode,
        "lens_description_sha256": lens_description_sha256,
        "prompt_version": PROMPT_VERSION,
        "generation_config": GENERATION_CONFIG,
        "repeat_index": repeat_index,
    }
    return sha256_text(json.dumps(value, sort_keys=True, separators=(",", ":")))


@dataclass(frozen=True)
class QwenResult:
    timestamp_utc: str
    status: str
    raw_model_answer: str
    raw_response: dict | None
    latency_ms: float
    time_to_first_token_ms: float | None
    usage: dict
    tokens_per_second: float | None
    attempts: int
    retries: int
    error: dict | None
    cache_hit: bool


class QwenClient:
    def __init__(
        self,
        base_url: str,
        cache_root: Path,
        model_sha256: str,
        *,
        max_retries: int = 3,
        timeout_seconds: float = 180.0,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.cache_root = cache_root
        self.model_sha256 = model_sha256
        self.max_retries = max_retries
        self.timeout_seconds = timeout_seconds

    def _request(self, body: dict) -> tuple[str, dict, dict, float | None]:
        request = Request(
            f"{self.base_url}/v1/chat/completions",
            data=json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        chunks = []
        pieces = []
        usage = {}
        timings = {}
        first_token_ms = None
        started = time.perf_counter()
        with urlopen(request, timeout=self.timeout_seconds) as response:
            for raw_line in response:
                line = raw_line.decode("utf-8", errors="replace").strip()
                if not line.startswith("data:"):
                    continue
                payload = line[5:].strip()
                if payload == "[DONE]":
                    break
                chunk = json.loads(payload)
                chunks.append(chunk)
                if chunk.get("usage"):
                    usage = chunk["usage"]
                if chunk.get("timings"):
                    timings = chunk["timings"]
                for choice in chunk.get("choices", []):
                    content = choice.get("delta", {}).get("content")
                    if content:
                        if first_token_ms is None:
                            first_token_ms = (time.perf_counter() - started) * 1000
                        pieces.append(content)
        return "".join(pieces), {"chunks": chunks, "timings": timings}, usage, first_token_ms

    def generate(
        self,
        *,
        question_id: str,
        question: str,
        mode: str,
        lens_text: str | None,
        lens_description_sha256: str | None,
        repeat_index: int = 0,
    ) -> QwenResult:
        key = cache_key(
            self.model_sha256,
            question_id,
            mode,
            lens_description_sha256,
            repeat_index,
        )
        cache_path = self.cache_root / f"{key}.json"
        if cache_path.is_file():
            value = json.loads(cache_path.read_text(encoding="utf-8"))
            value.pop("cached_at_utc", None)
            value.pop("cache_key", None)
            return QwenResult(**value, cache_hit=True)
        body = {
            "model": MODEL_ID,
            "messages": [
                {"role": "system", "content": SYSTEM_INSTRUCTION},
                {
                    "role": "user",
                    "content": request_text(question, mode, lens_text),
                },
            ],
            **GENERATION_CONFIG,
        }
        attempts = 0
        retries = 0
        error = None
        raw_answer = ""
        raw_response = None
        usage = {}
        first_token_ms = None
        request_timestamp_utc = datetime.now(timezone.utc).isoformat()
        started = time.perf_counter()
        while attempts <= self.max_retries:
            attempts += 1
            try:
                raw_answer, raw_response, usage, first_token_ms = self._request(body)
                if raw_answer:
                    break
                error = {"type": "empty_answer"}
            except HTTPError as exc:
                raw = exc.read().decode("utf-8", errors="replace")
                error = {"type": "http", "code": exc.code, "message": raw[:1000]}
                if exc.code < 500 and exc.code != 429:
                    break
            except (URLError, TimeoutError, OSError, json.JSONDecodeError) as exc:
                error = {"type": "transport", "message": str(exc)}
            if attempts <= self.max_retries:
                retries += 1
                time.sleep(min(10.0, 2 ** (attempts - 1) + random.random()))
        latency_ms = (time.perf_counter() - started) * 1000
        completion_tokens = int(usage.get("completion_tokens", 0) or 0)
        generation_seconds = max(0.0, (latency_ms - (first_token_ms or latency_ms)) / 1000)
        timings = (raw_response or {}).get("timings", {})
        tokens_per_second = timings.get("predicted_per_second")
        if tokens_per_second is None and completion_tokens and generation_seconds:
            tokens_per_second = completion_tokens / generation_seconds
        result = {
            "timestamp_utc": request_timestamp_utc,
            "status": "ok" if raw_answer else "inference_failed",
            "raw_model_answer": raw_answer,
            "raw_response": raw_response,
            "latency_ms": latency_ms,
            "time_to_first_token_ms": first_token_ms,
            "usage": usage,
            "tokens_per_second": tokens_per_second,
            "attempts": attempts,
            "retries": retries,
            "error": None if raw_answer else error,
        }
        if result["status"] != "ok":
            return QwenResult(**result, cache_hit=False)
        self.cache_root.mkdir(parents=True, exist_ok=True)
        cache_value = {
            **result,
            "cached_at_utc": datetime.now(timezone.utc).isoformat(),
            "cache_key": key,
        }
        temporary = cache_path.with_suffix(".tmp")
        temporary.write_text(
            json.dumps(cache_value, ensure_ascii=False, separators=(",", ":"), allow_nan=False),
            encoding="utf-8",
            newline="\n",
        )
        temporary.replace(cache_path)
        cache_value.pop("cached_at_utc")
        cache_value.pop("cache_key")
        return QwenResult(**cache_value, cache_hit=False)
